      "bodyHtml": "<!DOCTYPE html><html lang=\"pt\"><head><meta charset=\"utf-8\"/><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"/></head>\n<body style=\"margin:0;padding:0;background:#f0f2f5;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;-webkit-font-smoothing:antialiased;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f0f2f5;padding:32px 16px;\">\n<tr><td align=\"center\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:600px;width:100%;\">\n<tr><td style=\"text-align:center;padding:0 0 24px;\">{{#if company_logo}}<img src=\"{{company_logo}}\" alt=\"Parallly\" style=\"height:36px;\"/>{{/if}}</td></tr>\n<tr><td style=\"background:#fff;border-radius:16px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,.06);\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr><td style=\"height:4px;background:linear-gradient(90deg,#3897f0,#6c5ce7);\"></td></tr></table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\">\n<tr><td style=\"background:linear-gradient(135deg,#10b981,#059669);padding:40px 32px;text-align:center;\">\n<p style=\"margin:0 0 8px;font-size:40px;line-height:1;\">&#9989;</p>\n<h1 style=\"margin:0 0 8px;color:#fff;font-size:26px;font-weight:700;\">Pagamento confirmado</h1>\n<p style=\"margin:0;font-size:15px;color:rgba(255,255,255,.9);\">Obrigado por continuar confiando na Parallly</p>\n</td></tr></table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\">\n<tr><td style=\"padding:32px;\">\n<p style=\"margin:0 0 4px;font-size:16px;color:#1f2937;\">Olá <strong>{{customer_name}}</strong>,</p>\n<p style=\"margin:0 0 24px;font-size:14px;color:#6b7280;line-height:1.6;\">Recebemos seu pagamento com sucesso. Sua assinatura continua ativa e todas as suas ferramentas estão funcionando.</p>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f0fdf4;border-radius:12px;border:1px solid #bbf7d0;margin-bottom:24px;\">\n<tr><td style=\"padding:20px;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\">\n<tr><td style=\"padding:6px 0;font-size:13px;color:#6b7280;\">Plano</td><td style=\"padding:6px 0;text-align:right;font-size:14px;font-weight:600;color:#1f2937;\">{{plan_name}}</td></tr>\n<tr><td colspan=\"2\" style=\"height:1px;background:#dcfce7;\"></td></tr>\n<tr><td style=\"padding:6px 0;font-size:13px;color:#6b7280;\">Valor cobrado</td><td style=\"padding:6px 0;text-align:right;font-size:14px;font-weight:600;color:#1f2937;\">{{amount_charged}} {{currency}}</td></tr>\n<tr><td colspan=\"2\" style=\"height:1px;background:#dcfce7;\"></td></tr>\n<tr><td style=\"padding:6px 0;font-size:13px;color:#6b7280;\">Próxima cobrança</td><td style=\"padding:6px 0;text-align:right;font-size:14px;font-weight:600;color:#1f2937;\">{{next_billing_date}}</td></tr>\n</table>\n</td></tr></table>\n{{#if invoice_url}}<div style=\"text-align:center;margin-bottom:24px;\"><a href=\"{{invoice_url}}\" style=\"font-size:13px;color:#3897f0;text-decoration:none;font-weight:600;\">&#128196; Ver recibo completo</a></div>{{/if}}\n<div style=\"text-align:center;padding:4px 0 8px;\"><a href=\"{{dashboard_url}}\" style=\"display:inline-block;padding:14px 44px;background:linear-gradient(135deg,#3897f0,#2b7cd4);color:#fff;font-size:15px;font-weight:600;text-decoration:none;border-radius:10px;box-shadow:0 4px 14px rgba(56,151,240,.3);\">Ir ao meu painel</a></div>\n<p style=\"margin:16px 0 0;text-align:center;font-size:12px;color:#9ca3af;\">Dúvidas sobre sua fatura? <a href=\"mailto:it.executive@parallext.com\" style=\"color:#3897f0;text-decoration:none;\">Fale conosco</a></p>\n</td></tr></table>\n</td></tr>\n<tr><td style=\"text-align:center;padding:24px 0 8px;\">\n<p style=\"margin:0 0 4px;font-size:12px;color:#9ca3af;\">Parallly &mdash; Automação conversacional inteligente</p>\n<p style=\"margin:0;font-size:11px;color:#d1d5db;\"><a href=\"https://parallly-chat.cloud\" style=\"color:#3897f0;text-decoration:none;\">parallly-chat.cloud</a> &middot; <a href=\"mailto:it.executive@parallext.com\" style=\"color:#3897f0;text-decoration:none;\">Suporte</a></p>\n</td></tr>\n</table>\n</td></tr></table>\n</body></html>"
